SourceCode.Declaration:
/// <summary>
/// Business event to provide the extract of duty per case value after the 'Duty Roll Monthly' batch job is completed.
/// Created for the task - CB799.
/// </summary>
[BusinessEvents(classStr(METDutyRollMonthlyBusinessEventsContract),
    "@MET:MonthlyDutyRoll",
    "@MET:DutyRollBusinessEventDesc",
    ModuleAxapta::Inventory)]
internal final class METDutyRollMonthlyBusinessEvents extends BusinessEventsBase
{
    METDutyRollMonthlyContract contract;

}

Method.Source:
    /// <summary>
    /// To call the parm method of the business event.
    /// </summary>
    /// <param name = "_contract">METDutyRollMonthlyContract</param>
    /// <returns>METDutyRollMonthlyBusinessEvents</returns>
    public static METDutyRollMonthlyBusinessEvents newFromDutyRollMonthly(METDutyRollMonthlyContract _contract)
    {
        METDutyRollMonthlyBusinessEvents businessEvent = new METDutyRollMonthlyBusinessEvents();
        
        businessEvent.parmContract(_contract);

        return businessEvent;
    }

/// <summary>
/// Returns <c>METDutyRollMonthlyContract</c>
/// </summary>
/// <param name = "_contract">METDutyRollMonthlyContract</param>
/// <returns>METDutyRollMonthlyContract</returns>
private METDutyRollMonthlyContract parmContract(METDutyRollMonthlyContract _contract = contract)
{
    contract = _contract;
    return contract;
}

    /// <summary>
    /// Build contract for the business event.
    /// </summary>
    /// <returns>BusinessEventsContract</returns>

    [Wrappable(true), Replaceable(true)]
    public BusinessEventsContract buildContract()
    {
        return METDutyRollMonthlyBusinessEventsContract::sendEvent(contract);
    }
